<script setup lang="ts">
import {computed,ref} from 'vue';import {useApp} from '../stores/app';import Icon from '../components/Icon.vue';import {volume,timeLabel} from '../core/logic';
const app=useApp(),weight=ref<number|undefined>(),day=ref(app.today),range=ref('30'),message=ref(''),busy=ref(false);
const rows=computed(()=>{if(range.value==='all')return app.data.weights;const cutoff=new Date();cutoff.setDate(cutoff.getDate()-Number(range.value));return app.data.weights.filter(w=>new Date(w.day+'T12:00:00')>=cutoff);});
const min=computed(()=>Math.floor(Math.min(...rows.value.map(x=>x.kg))-1));const max=computed(()=>Math.ceil(Math.max(...rows.value.map(x=>x.kg))+1));
const points=computed(()=>{const times=rows.value.map(w=>new Date(w.day+'T12:00:00').getTime());const first=times[0]||0;const span=(times.at(-1)||0)-first;return rows.value.map((w,i)=>`${40+(span?(times[i]!-first)/span:0.5)*620},${190-(w.kg-min.value)/(max.value-min.value)*155}`).join(' ');});
async function add(){busy.value=true;try{if(!weight.value)return;await app.addWeight(weight.value,day.value);weight.value=undefined;message.value='Weight saved.';}catch(e){message.value=String(e);}finally{busy.value=false;}}
</script>
<template><section class="page-heading"><div><div class="eyebrow">PROGRESS OVER PERFECTION</div><h1>The work <span>adds up.</span></h1><p>A clear view of your training and body-weight history.</p></div><select v-model="range" aria-label="Weight chart range" class="range-select"><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="90">Last 90 days</option><option value="all">All time</option></select></section><div class="three-stats"><section class="card stat-card"><span class="stat-top">Current weight</span><strong>{{app.data.profile.weight||'—'}}<small>kg</small></strong></section><section class="card stat-card"><span class="stat-top">Your goal</span><strong>{{app.data.profile.targetWeight||'—'}}<small>kg</small></strong></section><section class="card stat-card"><span class="stat-top">Total sessions</span><strong>{{app.completed.length}}<small>completed</small></strong></section></div><div class="two-columns wide-left"><section class="card"><div class="section-title"><h3>Weight over time</h3><span class="tiny-badge">YOUR ACTUAL LOGS</span></div><div v-if="rows.length" class="chart-container"><svg viewBox="0 0 700 240" role="img" aria-label="Weight trend, with exact values in the table below"><g stroke="currentColor" opacity=".12"><path d="M40 35H670M40 112H670M40 190H670"/></g><g fill="currentColor" font-size="11" opacity=".6"><text x="0" y="39">{{max}} kg</text><text x="0" y="194">{{min}} kg</text><text x="40" y="226">{{rows[0]?.day}}</text><text x="570" y="226">{{rows.at(-1)?.day}}</text></g><polyline :points="points" fill="none" stroke="#a1cf53" stroke-width="3"/><circle v-for="(p,i) in points.split(' ')" :key="i" :cx="p.split(',')[0]" :cy="p.split(',')[1]" r="4" fill="#c4f568"/></svg></div><div v-else class="empty"><Icon name="ChartNoAxesCombined" :size="38"/><h3>Your story is just starting.</h3><p>Add a weigh-in to see your trend.</p></div><details v-if="rows.length"><summary>View {{rows.length}} recorded measurements</summary><table><thead><tr><th>Date</th><th>Weight</th></tr></thead><tbody><tr v-for="w in rows" :key="w.id"><td>{{w.day}}</td><td>{{w.kg}} kg</td></tr></tbody></table></details><p class="fine muted">Daily weight can fluctuate. Look at your longer-term trend; no target-date prediction is made.</p></section><section class="card"><div class="section-title"><h3>Add a weigh-in</h3><Icon name="Plus"/></div><form class="stack" @submit.prevent="add"><label>Body weight (kg)<input v-model.number="weight" type="number" min="20" max="400" step="0.1" required placeholder="e.g. 55.0"></label><label>Date<input v-model="day" type="date" :max="app.today" required></label><button class="button primary" :disabled="busy">Save measurement</button></form><p class="muted fine">A new entry for the same day replaces that day’s measurement.</p><p class="lime-text" role="status">{{message}}</p></section></div><section class="card history"><div class="section-title"><h3>Workout history</h3><Icon name="Dumbbell"/></div><div v-if="!app.completed.length" class="empty"><p>Finish a workout to start your history.</p><RouterLink to="/train" class="button secondary">Go to training<Icon name="ArrowRight" :size="16"/></RouterLink></div><details v-for="session in app.completed" :key="session.id" class="history-item"><summary><span><strong>{{session.name}}</strong><small>{{session.day}} · {{session.sets.length}} sets</small></span><span>{{timeLabel(((session.end||session.start)-session.start)/1000)}}<small>{{volume([session])}} kg × reps</small></span></summary><p>{{session.sets.reduce((sum,s)=>sum+s.reps,0)}} repetitions · {{new Set(session.sets.map(s=>s.exerciseId)).size}} exercises recorded</p></details></section></template>
